function h(n: number): number {
  for (let i = 0; i < 2; i++) { if (i === 1) { var last = i + n; } }
  return last === undefined ? -1 : last;
}
function w(flag: boolean): string {
  console.log(typeof q);
  if (flag) { var q = "set"; }
  return String(q);
}
function main(): void {
  f();
  console.log(h(5), w(true), w(false));
}
